mapper.select:
SELECT c.CUSTOMER_ID, c.CUSTOMER_CODE, c.CUSTOMER_NAME, c.CUSTOMER_CATEGORY, c.CUSTOMER_STATUS, c.CREDIT_CODE, c.LEGAL_REPRESENTATIVE, c.REGISTERED_ADDRESS, c.CONTACT_PERSON, c.CONTACT_PHONE, c.CONTACT_EMAIL, c.FAX_NUMBER, c.CONTACT_ADDRESS, c.BANK_NAME, c.BANK_ACCOUNT, c.CREDIT_LEVEL, c.CREDIT_LIMIT, c.COLLECTION_METHOD, c.CREDIT_TERMS, c.REMARKS, c.TENANT_ID, c.ORG_ID, c.CREATE_TIME, c.CREATE_BY, c.UPDATE_TIME, c.UPDATE_BY, c.IS_DELETED, CASE c.CUSTOMER_CATEGORY WHEN 1 THEN '重要客户' WHEN 2 THEN '一般客户' WHEN 3 THEN '潜在客户' ELSE '其他' END AS customerCategoryName, CASE c.CUSTOMER_STATUS WHEN 1 THEN '正常' WHEN 2 THEN '暂停' WHEN 3 THEN '黑名单' ELSE '未知' END AS customerStatusName, NVL((SELECT SUM(r.REMAINING_AMOUNT) FROM TBL_AR_RECEIVABLE r WHERE r.CUSTOMER_ID = c.CUSTOMER_ID AND r.IS_DELETED = 0), 0) AS receivableAmount FROM TBL_AR_CUSTOMER c WHERE c.IS_DELETED = 0
AND c.TENANT_ID = #{param.tenantId}
AND c.CUSTOMER_CODE LIKE '%' || #{param.customerCode} || '%'
AND c.CUSTOMER_NAME LIKE '%' || #{param.customerName} || '%'
AND c.CUSTOMER_CATEGORY = #{param.customerCategory}
AND c.CUSTOMER_STATUS = #{param.customerStatus}
AND c.CREDIT_LEVEL = #{param.creditLevel}
AND c.CONTACT_PERSON LIKE '%' || #{param.contactPerson} || '%'
AND c.CONTACT_PHONE LIKE '%' || #{param.contactPhone} || '%'
AND c.ORG_ID = #{param.orgId}
ORDER BY c.CREATE_TIME DESC

SELECT COUNT(1) FROM TBL_AR_CUSTOMER
WHERE CUSTOMER_CODE = #{customerCode} AND TENANT_ID = #{tenantId} AND IS_DELETED = 0

    AND CUSTOMER_ID != #{customerId}
